export const GLOBAL_CITIZEN_ACTIVITIES = [
// PHASE A — FONDASI (1-20)
{n:1,type:"mcq",micro:"Apa itu warga dunia",q:"'Warga dunia' (global citizen) adalah seseorang yang...",options:["melupakan negaranya sendiri demi dunia","menyadari dirinya bagian dari keluarga besar umat manusia & peduli pada kesejahteraan orang di mana pun, sambil tetap mencintai negerinya sendiri","hanya peduli pada negara-negara besar"],answer:1,explain:"Menjadi warga dunia menambahkan lapisan identitas, bukan mengganti identitas lokal & nasional kita.",hint:"Peduli dunia + tetap cinta negeri sendiri."},
{n:2,type:"mcq",micro:"Lapisan identitas",q:"Seseorang bisa sekaligus merasa menjadi bagian dari...",options:["hanya satu lingkaran identitas saja","keluarganya, kotanya, negaranya, & dunia — semua lapisan ini bisa hidup berdampingan","tidak ada identitas yang penting"],answer:1,explain:"Identitas manusia berlapis: keluarga, daerah, bangsa, & kemanusiaan global sekaligus.",hint:"Keluarga → kota → negara → dunia, berdampingan."},
{n:3,type:"mcq",micro:"Hak asasi manusia dasar",q:"Gagasan dasar hak asasi manusia adalah bahwa...",options:["hanya orang tertentu yang berhak dihormati martabatnya","setiap manusia, di mana pun ia lahir, punya martabat & hak dasar yang sama untuk dihormati (aman, bebas dari kekerasan, & diperlakukan adil)","hak seseorang tergantung dari negaranya"],answer:1,explain:"Hak asasi manusia dianggap berlaku universal bagi semua orang, bukan hanya sebagian.",hint:"Berlaku untuk semua manusia, di mana pun."},
{n:4,type:"tf",micro:"Warga dunia & warga negara",q:"Benar atau Salah: Menjadi warga dunia yang peduli pada kemanusiaan global tidak bertentangan dengan menjadi warga negara yang baik & mencintai negerinya sendiri.",answer:true,explain:"Keduanya bisa berjalan bersama — mencintai rumah sendiri sekaligus peduli pada tetangga dunia.",hint:"Bisa keduanya sekaligus, tidak bertentangan."},
{n:5,type:"mcq",micro:"Mulai dari yang dekat",q:"Menjadi warga dunia yang baik biasanya dimulai dari...",options:["langsung mencoba menyelesaikan masalah di negara yang jauh","berlatih peduli & bertanggung jawab di lingkungan terdekat (keluarga, sekolah, tetangga) lebih dulu","mengabaikan lingkungan sendiri"],answer:1,explain:"Kebiasaan peduli & bertanggung jawab yang dilatih di lingkungan dekat menjadi fondasi untuk kepedulian yang lebih luas.",hint:"Latihan dimulai dari yang dekat."},
{n:6,type:"mcq",micro:"Rasa ingin tahu tentang dunia",q:"Sikap dasar warga dunia terhadap tempat & orang yang belum ia kenal:",options:["acuh tak acuh","penasaran untuk belajar & terbuka pada perspektif baru","curiga & menjaga jarak selalu"],answer:1,explain:"Rasa ingin tahu yang hormat adalah pintu masuk menjadi warga dunia yang baik.",hint:"Penasaran & terbuka belajar."},
{n:7,type:"tf",micro:"Empati sebagai dasar",q:"Benar atau Salah: Empati — kemampuan membayangkan perasaan orang lain — adalah salah satu dasar penting untuk peduli pada orang yang belum pernah kita temui di tempat lain di dunia.",answer:true,explain:"Empati memungkinkan kita peduli pada orang yang jauh & berbeda dari kita, bukan hanya yang dekat.",hint:"Empati membuat kepedulian menjangkau yang jauh."},
{n:8,type:"mcq",micro:"Tanggung jawab bersama",q:"Sebagai bagian dari dunia yang terhubung, kita ikut memikul tanggung jawab untuk...",options:["tidak melakukan apa-apa","memperlakukan orang lain & lingkungan dengan adil, meski dampak tindakan kita tidak selalu langsung terlihat","hanya memikirkan diri sendiri"],answer:1,explain:"Pilihan kita (konsumsi, informasi yang disebar, sikap pada orang lain) punya dampak yang bisa menjangkau lebih luas dari yang kita sadari.",hint:"Tanggung jawab meski dampaknya tak selalu terlihat."},
{n:9,type:"mcq",micro:"Belajar tentang dunia",q:"Cara sederhana mulai belajar menjadi warga dunia:",options:["mengikuti berita & belajar tentang budaya, isu, & orang dari berbagai tempat, dengan sumber yang tepercaya","menghafal nama semua negara saja","menunggu dewasa dulu"],answer:0,explain:"Belajar bisa dimulai kapan saja, lewat membaca, mendengarkan, & rasa ingin tahu yang tulus.",hint:"Belajar dari sumber tepercaya tentang dunia."},
{n:10,type:"tf",micro:"Siapa pun bisa jadi warga dunia",q:"Benar atau Salah: Menjadi warga dunia yang baik hanya mungkin dilakukan oleh orang dewasa yang kaya & sering bepergian ke luar negeri.",answer:false,explain:"Sebaliknya, siapa pun — termasuk pelajar yang belum pernah bepergian jauh — bisa menjadi warga dunia lewat sikap, belajar, & tindakan kecil sehari-hari.",hint:"Siapa pun bisa, tidak perlu kaya atau sering bepergian."},
{n:11,type:"open",micro:"Lapisan identitasmu",q:"Tuliskan bagaimana kamu menggambarkan dirimu dalam beberapa lapisan identitas: keluarga, daerah/kota, negara, & dunia.",sample:"Aku adalah anak dari keluargaku, tinggal di sebuah kota di Indonesia, warga negara Indonesia yang bangga pada budayanya, & sekaligus bagian dari umat manusia di seluruh dunia yang ingin belajar & peduli pada sesama, di mana pun mereka berada.",explain:"Menyadari lapisan identitas ini membantu memahami bahwa kepedulian global tidak menggantikan, melainkan menambah, identitas kita yang lain.",hint:"4 lapisan: keluarga, kota/daerah, negara, dunia."},
{n:12,type:"mcq",micro:"Nilai kemanusiaan bersama",q:"Nilai yang biasanya dianggap penting oleh hampir semua budaya di dunia:",options:["kejujuran, kasih sayang pada keluarga, & keadilan","hanya nilai yang dianut satu negara saja","tidak ada nilai yang sama di antara budaya berbeda"],answer:0,explain:"Meski cara mengungkapkannya berbeda, banyak nilai dasar (kejujuran, kasih sayang, keadilan) muncul di hampir semua budaya.",hint:"Beberapa nilai dasar muncul di mana-mana."},
{n:13,type:"mcq",micro:"Warga dunia & tindakan kecil",q:"Contoh tindakan kecil sehari-hari yang mencerminkan sikap warga dunia:",options:["memeriksa kebenaran berita sebelum membagikannya, & bersikap ramah pada teman dari latar belakang berbeda","mengabaikan berita dari luar negeri sepenuhnya","hanya berteman dengan yang persis sama dengan kita"],answer:0,explain:"Sikap warga dunia terlihat dari kebiasaan kecil sehari-hari, bukan hanya tindakan besar & jarang.",hint:"Kebiasaan kecil sehari-hari."},
{n:14,type:"tf",micro:"Warga dunia tetap punya akar",q:"Benar atau Salah: Menjadi warga dunia berarti kita harus melupakan atau meninggalkan identitas budaya & negara asal kita.",answer:false,explain:"Sebaliknya, warga dunia yang baik tetap berakar pada identitasnya sendiri sambil terbuka pada dunia yang lebih luas.",hint:"Tetap berakar, sambil terbuka."},
{n:15,type:"mcq",micro:"Mendengarkan suara berbeda",q:"Bagian penting menjadi warga dunia adalah bersedia...",options:["hanya mendengar orang yang sependapat","mendengarkan & mempertimbangkan sudut pandang orang dari latar belakang yang sangat berbeda darimu","mengabaikan semua pendapat yang berbeda"],answer:1,explain:"Mendengarkan sudut pandang berbeda memperluas pemahaman & mengurangi prasangka.",hint:"Dengarkan sudut pandang yang berbeda darimu."},
{n:16,type:"mcq",micro:"Dunia sebagai rumah bersama",q:"Metafora 'dunia adalah rumah bersama umat manusia' mengingatkan kita bahwa...",options:["kita harus tinggal di satu tempat yang sama","tindakan kita di satu bagian rumah (dunia) bisa memengaruhi bagian lain, sehingga kita perlu saling menjaga","rumah orang lain bukan urusan kita"],answer:1,explain:"Seperti anggota keluarga menjaga rumah bersama, warga dunia menjaga planet & kesejahteraan bersama.",hint:"Satu rumah besar, saling menjaga."},
{n:17,type:"order",micro:"Langkah menjadi warga dunia yang baik",q:"Urutkan langkah awal menjadi warga dunia yang baik:",items:["Kenali & rawat identitas serta lingkungan terdekatmu dengan baik","Belajar tentang dunia, budaya, & isu global dari sumber tepercaya","Berlatih empati & mendengarkan sudut pandang yang berbeda","Ambil tindakan kecil yang bertanggung jawab, lokal maupun yang terhubung ke isu global"],answer:[0,1,2,3],explain:"Mulai dari akar sendiri → belajar tentang dunia → berempati → bertindak.",hint:"Rawat yang dekat dulu, bertindak di akhir."},
{n:18,type:"mcq",micro:"Perbedaan bukan alasan memusuhi",q:"Bertemu orang dengan keyakinan, kebangsaan, atau pandangan yang sangat berbeda darimu seharusnya...",options:["membuatmu langsung memusuhi mereka","tetap bisa disikapi dengan hormat & rasa ingin tahu, tanpa harus setuju pada semua hal","membuatmu berhenti berpikir"],answer:1,explain:"Menghormati seseorang tidak mengharuskan kita setuju dengan semua pandangannya.",hint:"Hormat tak berarti harus setuju semua."},
{n:19,type:"tf",micro:"Warga dunia terus belajar",q:"Benar atau Salah: Menjadi warga dunia adalah proses belajar yang berlangsung terus-menerus sepanjang hidup, bukan status yang bisa 'selesai' dicapai sekali.",answer:true,explain:"Dunia terus berubah, & pemahaman kita tentangnya juga perlu terus diperbarui.",hint:"Proses berkelanjutan, tak pernah 'selesai'."},
{n:20,type:"mcq",micro:"Ringkasan Fondasi",q:"Inti menjadi warga dunia:",options:["menyadari kemanusiaan bersama & martabat semua orang, tetap berakar pada identitas sendiri, terbuka belajar, berempati, & bertanggung jawab atas dampak tindakan kita","meninggalkan negara & budaya sendiri","hanya peduli pada negara-negara besar & terkenal"],answer:0,explain:"Warga dunia yang baik menyatukan akar yang kuat dengan pandangan yang luas & hati yang terbuka.",hint:"Kemanusiaan bersama + akar sendiri + terbuka + tanggung jawab."},
// PHASE B — PEMAHAMAN (21-40)
{n:21,type:"classify",micro:"Sikap warga dunia atau bukan",q:"Kelompokkan setiap sikap berikut:",items:["Memeriksa kebenaran berita sebelum membagikannya ke orang lain","Menertawakan aksen atau logat orang dari daerah lain","Bersikap ramah & ingin tahu pada teman baru dari negara lain","Menganggap masalah di negara lain 'bukan urusanku sama sekali'"],groups:["Mencerminkan sikap warga dunia yang baik","Tidak mencerminkan sikap warga dunia yang baik"],answer:{"Mencerminkan sikap warga dunia yang baik":["Memeriksa kebenaran berita sebelum membagikannya ke orang lain","Bersikap ramah & ingin tahu pada teman baru dari negara lain"],"Tidak mencerminkan sikap warga dunia yang baik":["Menertawakan aksen atau logat orang dari daerah lain","Menganggap masalah di negara lain 'bukan urusanku sama sekali'"]},explain:"Sikap warga dunia terlihat dari kebiasaan kecil: kejujuran, keramahan, & kepedulian, bukan sekadar pengetahuan.",hint:"Mana yang menunjukkan hormat & peduli, mana yang tidak."},
{n:22,type:"mcq",micro:"Hak & tanggung jawab",q:"Menjadi warga (baik warga negara maupun warga dunia) biasanya melibatkan...",options:["hanya hak tanpa tanggung jawab","hak untuk dihormati & diperlakukan adil, sekaligus tanggung jawab untuk menghormati & tidak merugikan orang lain","hanya tanggung jawab tanpa hak apa pun"],answer:1,explain:"Kewargaan yang sehat, di tingkat mana pun, adalah keseimbangan antara hak & tanggung jawab.",hint:"Hak & tanggung jawab berjalan bersama."},
{n:23,type:"mcq",micro:"Perbedaan pandangan tentang dunia",q:"Orang dari negara berbeda bisa punya pandangan berbeda tentang isu global yang sama karena...",options:["salah satu pasti bodoh","perbedaan pengalaman, kepentingan, & konteks yang membentuk cara pandang mereka","tidak ada alasan tertentu"],answer:1,explain:"Memahami mengapa pandangan berbeda muncul membantu kita berdiskusi dengan lebih matang, bukan sekadar menghakimi.",hint:"Pengalaman & konteks yang berbeda membentuk pandangan."},
{n:24,type:"mcq",micro:"Konsumen global yang bertanggung jawab",q:"Sebagai 'konsumen global', pilihan yang mencerminkan tanggung jawab:",options:["membeli apa pun tanpa berpikir sama sekali","sesekali mempertimbangkan dari mana barang berasal & bagaimana dampaknya pada orang & lingkungan, sesuai kemampuan","memboikot semua produk dari luar negeri"],answer:1,explain:"Menjadi konsumen yang sadar tidak berarti sempurna, tetapi mulai mempertimbangkan dampak pilihan kita.",hint:"Mulai mempertimbangkan dampak, sesuai kemampuan."},
{n:25,type:"tf",micro:"Belajar bahasa sebagai jembatan",q:"Benar atau Salah: Belajar bahasa asing, meski hanya sedikit, bisa membantu seseorang menjadi warga dunia yang lebih terhubung dengan orang dari negara lain.",answer:true,explain:"Bahasa membuka pintu komunikasi & pemahaman lintas budaya, meski hanya kemampuan dasar.",hint:"Bahasa membuka pintu komunikasi."},
{n:26,type:"mcq",micro:"Menghadapi berita dari luar negeri",q:"Saat membaca berita tentang peristiwa di negara lain, sikap warga dunia yang kritis:",options:["percaya begitu saja pada judul","cek dari beberapa sumber tepercaya sebelum menyimpulkan atau membagikannya","abaikan semua berita luar negeri"],answer:1,explain:"Literasi media adalah bagian penting dari kewargaan global yang bertanggung jawab.",hint:"Cek beberapa sumber tepercaya."},
{n:27,type:"mcq",micro:"Solidaritas tanpa harus hadir langsung",q:"Kamu tidak bisa pergi langsung membantu korban bencana di negara lain. Cara menunjukkan solidaritas yang tetap bermakna:",options:["tidak melakukan apa-apa karena tidak bisa hadir langsung","ikut penggalangan dana resmi, menyebarkan informasi yang akurat, atau mendoakan & mendukung dengan cara lain yang kamu mampu","merasa bersalah tanpa melakukan apa pun"],answer:1,explain:"Solidaritas global tidak selalu butuh kehadiran fisik; banyak cara bermakna sesuai kemampuan masing-masing.",hint:"Banyak cara mendukung tanpa harus hadir langsung."},
{n:28,type:"open",micro:"Nilai bersama & ekspresi berbeda",q:"Pilih satu nilai yang menurutmu dianut hampir semua budaya (mis. kejujuran, kasih sayang, keadilan). Jelaskan bagaimana nilai itu mungkin diekspresikan berbeda-beda di berbagai budaya.",sample:"Nilai: menghormati tamu. Di budayaku, ini terlihat dari menyuguhkan makanan & minuman begitu tamu datang. Aku pernah membaca bahwa di beberapa budaya lain, menghormati tamu terlihat dari memberi tempat duduk terbaik atau hadiah kecil saat berkunjung. Bentuknya berbeda, tapi semangat menyambut & menghargai tamu sama-sama ada.",explain:"Menemukan nilai bersama di balik ekspresi budaya yang berbeda memperkuat rasa kemanusiaan bersama.",hint:"1 nilai + ekspresi berbeda di berbagai budaya."},
{n:29,type:"mcq",micro:"Peran pelajar dalam isu global",q:"Pelajar bisa berkontribusi pada isu global lewat...",options:["hanya menunggu sampai dewasa & punya kekuasaan","belajar, menyebarkan informasi yang benar, mengubah kebiasaan sehari-hari, & mengajak orang lain peduli sesuai kemampuannya sebagai pelajar","tidak ada peran untuk pelajar sama sekali"],answer:1,explain:"Kontribusi tidak menunggu usia atau jabatan tertentu; ada banyak cara sesuai posisi kita sekarang.",hint:"Peran yang sesuai kemampuan pelajar."},
{n:30,type:"order",micro:"Dari empati ke aksi",q:"Urutkan bagaimana empati bisa berkembang menjadi aksi nyata sebagai warga dunia:",items:["Mendengar atau membaca tentang situasi orang di tempat lain","Membayangkan & memahami perasaan mereka (empati)","Mencari tahu lebih lanjut & mempertimbangkan apa yang bisa membantu","Melakukan tindakan kecil yang sesuai kemampuan"],answer:[0,1,2,3],explain:"Empati tanpa tindakan tetap berharga, tetapi empati yang berujung tindakan kecil membawa dampak nyata.",hint:"Mendengar dulu, bertindak di akhir."},
{n:31,type:"mcq",micro:"Menghormati kedaulatan & perbedaan sistem",q:"Negara-negara di dunia punya sistem pemerintahan & aturan yang berbeda-beda. Sikap warga dunia yang matang:",options:["menganggap sistem negaranya sendiri harus dipakai semua negara","memahami bahwa tiap negara punya sejarah & konteks yang membentuk sistemnya, sambil tetap menjunjung nilai hak asasi manusia yang universal","tidak peduli sistem apa pun yang dipakai negara mana pun"],answer:1,explain:"Menghormati keberagaman sistem tidak berarti mengabaikan standar hak asasi manusia yang mendasar.",hint:"Hormati keberagaman sistem, tetap junjung HAM dasar."},
{n:32,type:"tf",micro:"Semua suara berharga",q:"Benar atau Salah: Pendapat & pengalaman orang dari negara kecil atau kurang dikenal sama berharganya untuk didengar seperti pendapat dari negara besar & terkenal.",answer:true,explain:"Ukuran atau ketenaran sebuah negara tidak menentukan nilai kemanusiaan atau kebijaksanaan warganya.",hint:"Ukuran negara tidak menentukan nilai suara warganya."},
{n:33,type:"mcq",micro:"Menjadi jembatan, bukan tembok",q:"Warga dunia yang baik cenderung berusaha menjadi...",options:["tembok yang memisahkan kelompok yang berbeda","jembatan yang menghubungkan orang dari latar belakang berbeda, lewat pengertian & komunikasi","penonton yang tidak peduli pada hubungan antarorang"],answer:1,explain:"Metafora jembatan menggambarkan peran menghubungkan, bukan memisahkan, orang-orang yang berbeda.",hint:"Menghubungkan, bukan memisahkan."},
{n:34,type:"mcq",micro:"Kewargaan digital global",q:"Karena banyak interaksi kini terjadi daring dengan orang dari berbagai negara, 'kewargaan digital' penting karena...",options:["dunia maya tidak butuh sopan santun","perilaku kita daring (kata-kata, informasi yang dibagikan) bisa memengaruhi orang di negara lain juga, sehingga tanggung jawab yang sama berlaku","internet hanya untuk hiburan"],answer:1,explain:"Etika sebagai warga dunia berlaku juga di ruang digital, tempat interaksi lintas negara terjadi setiap hari.",hint:"Etika warga dunia berlaku juga secara daring."},
{n:35,type:"mcq",micro:"Menyeimbangkan kebanggaan & rendah hati",q:"Sikap yang seimbang seorang warga dunia terhadap negaranya sendiri:",options:["bangga berlebihan sampai meremehkan negara lain","bangga & mencintai negerinya, sekaligus rendah hati bahwa negara lain juga punya kekuatan & hal baik untuk dipelajari","malu pada negaranya sendiri demi terlihat 'mendunia'"],answer:1,explain:"Kebanggaan yang sehat tidak butuh merendahkan pihak lain untuk terasa berarti.",hint:"Bangga pada negeri sendiri, tanpa merendahkan yang lain."},
{n:36,type:"open",micro:"Momen menjadi warga dunia",q:"Ceritakan satu momen (sekecil apa pun) ketika kamu merasa terhubung dengan orang atau isu di luar lingkunganmu sendiri.",sample:"Saat sekolahku menggalang dana untuk korban bencana di negara lain, aku ikut menyumbangkan sebagian uang jajanku. Meski jumlahnya kecil & aku tidak pernah bertemu langsung dengan orang yang terbantu, aku merasa menjadi bagian dari usaha bersama banyak orang untuk membantu sesama manusia yang sedang kesulitan, meski jauh di sana.",explain:"Momen-momen kecil seperti ini adalah bukti nyata bahwa siapa pun bisa menjadi bagian dari kepedulian global.",hint:"1 momen + perasaanmu saat itu."},
{n:37,type:"mcq",micro:"Menyikapi ketidaksetujuan global",q:"Kamu tidak setuju dengan kebijakan sebuah negara lain tentang suatu isu. Cara menyikapinya sebagai warga dunia:",options:["membenci semua orang dari negara itu","pisahkan ketidaksetujuanmu pada kebijakan dari sikap terhadap orang-orangnya, & sampaikan pandangan dengan cara yang beradab bila relevan","menganggap seluruh negara itu buruk"],answer:1,explain:"Kritik pada kebijakan berbeda dari kebencian pada orang atau bangsa secara keseluruhan.",hint:"Kritik kebijakan ≠ membenci orangnya."},
{n:38,type:"tf",micro:"Kerja sama mengalahkan kompetisi buta",q:"Benar atau Salah: Untuk masalah yang menyangkut kesejahteraan bersama (seperti kesehatan atau lingkungan), kerja sama antarnegara sering lebih efektif daripada persaingan yang saling menjatuhkan.",answer:true,explain:"Beberapa tantangan hanya bisa diatasi lewat kerja sama, bukan lewat sikap saling mengalahkan.",hint:"Kerja sama > saling menjatuhkan, untuk isu bersama."},
{n:39,type:"mcq",micro:"Memilih sumber yang beragam",q:"Untuk memahami sebuah isu global secara lebih utuh, berguna untuk...",options:["hanya membaca dari satu sumber yang paling sering muncul","membaca dari beberapa sumber tepercaya, idealnya termasuk sudut pandang dari negara/kelompok yang terlibat langsung","mengabaikan semua sumber & mengandalkan tebakan"],answer:1,explain:"Sumber yang beragam membantu melihat sebuah isu dari lebih dari satu sisi.",hint:"Beberapa sumber, termasuk suara langsung yang terlibat."},
{n:40,type:"mcq",micro:"Ringkasan Pemahaman",q:"Kewargaan global yang sehat menggabungkan...",options:["hak & tanggung jawab, kebanggaan & rendah hati, kritik yang adil & bukan kebencian, serta kebiasaan mencari informasi dari sumber yang beragam & tepercaya","hanya hak tanpa tanggung jawab","kebanggaan berlebihan tanpa rendah hati"],answer:0,explain:"Kematangan kewargaan global terlihat dari keseimbangan berbagai sikap ini dalam keseharian.",hint:"Hak & tanggung jawab, bangga & rendah hati, kritik adil, sumber beragam."},
// PHASE C — PENERAPAN (41-60)
{n:41,type:"mcq",micro:"Terapan: proyek 'warga dunia kecil'",q:"Kelasmu membuat proyek 'satu tindakan warga dunia per minggu' (mis. belajar satu fakta budaya, menghemat sumber daya, membantu teman baru). Manfaat proyek seperti ini:",options:["tidak ada manfaatnya","mengubah nilai abstrak menjadi kebiasaan nyata yang terukur & bisa dirayakan kemajuannya","hanya untuk nilai tugas semata"],answer:1,explain:"Proyek konkret membuat konsep kewargaan global terasa dekat & bisa dijalankan, bukan sekadar teori.",hint:"Mengubah nilai jadi kebiasaan nyata."},
{n:42,type:"mcq",micro:"Terapan: menyambut keluarga pengungsi/pindahan",q:"Sebuah keluarga pindahan dari daerah/negara lain (termasuk yang mengungsi karena konflik/bencana) tinggal di lingkunganmu. Sikap warga dunia yang baik:",options:["menjauhi mereka","menyambut dengan ramah, membantu mereka mengenal lingkungan, & menghormati privasi serta cerita mereka tanpa memaksa","menuntut mereka segera berbaur sepenuhnya seperti kita"],answer:1,explain:"Menyambut dengan hormat & kesabaran membantu keluarga baru merasa aman & diterima.",hint:"Sambut ramah, bantu, hormati privasi mereka."},
{n:43,type:"mcq",micro:"Terapan: menanggapi ujaran kebencian",q:"Kamu melihat komentar daring yang menghina sekelompok orang berdasarkan kebangsaan mereka. Respons yang berani & bertanggung jawab:",options:["ikut menambahkan komentar serupa","tidak menyebarkan/menyukai komentar itu, & bila memungkinkan melaporkannya atau menyuarakan pandangan yang lebih adil dengan tenang","diam saja tanpa peduli"],answer:1,explain:"Warga dunia yang baik berani menolak ujaran kebencian dengan cara yang aman & bertanggung jawab.",hint:"Jangan sebarkan, laporkan/tanggapi dengan tenang."},
{n:44,type:"open",micro:"Terapan: surat untuk teman di negara lain",q:"Tulis surat singkat (3-5 kalimat) untuk seorang teman bayangan seusiamu di negara lain, memperkenalkan dirimu & menanyakan sesuatu tentang kehidupannya.",sample:"Halo temanku, namaku [nama], aku tinggal di Indonesia & suka bermain sepak bola serta membaca komik. Aku penasaran bagaimana suasana sekolahmu sehari-hari & permainan apa yang paling disukai anak-anak di negaramu. Aku juga ingin tahu makanan khas apa yang paling kamu suka & apakah ada tradisi keluarga yang istimewa di negaramu. Semoga suatu hari kita bisa saling bercerita lebih banyak!",explain:"Latihan menulis surat lintas budaya melatih rasa ingin tahu & kemampuan memperkenalkan diri dengan hormat.",hint:"Perkenalkan diri + 2 pertanyaan tulus tentang hidupnya."},
{n:45,type:"mcq",micro:"Terapan: memilih proyek amal",q:"Kelasmu ingin mendukung satu isu global lewat penggalangan dana. Cara memilih dengan bijak:",options:["pilih yang paling ramai dibicarakan tanpa mengecek","cari lembaga yang kredibel & transparan, pahami bagaimana dana akan dipakai, & pastikan sesuai isu yang benar-benar dipedulikan kelas","asal pilih siapa saja yang meminta"],answer:1,explain:"Memilih dengan bijak memastikan bantuan benar-benar sampai & efektif.",hint:"Cek kredibilitas & transparansi lembaga."},
{n:46,type:"order",micro:"Terapan: menyiapkan diri untuk pertukaran budaya",q:"Kamu akan mengikuti program pertukaran pelajar singkat (langsung atau daring). Urutkan persiapan sebagai warga dunia yang baik:",items:["Pelajari dasar budaya & etika sopan santun negara/komunitas tujuan","Siapkan sikap terbuka & pertanyaan yang tulus untuk belajar","Selama program, dengarkan lebih banyak & amati sebelum menilai","Setelah program, bagikan & refleksikan apa yang dipelajari dengan hormat"],answer:[0,1,2,3],explain:"Persiapan yang matang dimulai jauh sebelum & berlanjut setelah pengalaman itu selesai.",hint:"Belajar dulu, refleksi di akhir."},
{n:47,type:"mcq",micro:"Terapan: menyikapi kekalahan tim nasional",q:"Tim olahraga negaramu kalah dari negara lain dalam pertandingan internasional. Sikap warga dunia yang sportif:",options:["menghina tim & pendukung lawan","kecewa boleh, tetapi tetap menghormati usaha & kemenangan lawan secara sportif","memusuhi negara lawan setelahnya"],answer:1,explain:"Sportivitas dalam kompetisi internasional adalah cerminan sikap warga dunia yang menghormati sesama, menang atau kalah.",hint:"Kecewa boleh, hormat tetap dijaga."},
{n:48,type:"tf",micro:"Terapan: kebiasaan hemat sumber daya",q:"Benar atau Salah: Kebiasaan menghemat air, listrik, & makanan di rumah adalah salah satu cara sederhana bertindak sebagai warga dunia yang bertanggung jawab, karena sumber daya bumi digunakan bersama semua orang.",answer:true,explain:"Kebiasaan kecil ini menghubungkan tindakan pribadi dengan tanggung jawab terhadap sumber daya bersama planet.",hint:"Sumber daya bumi dipakai bersama semua orang."},
{n:49,type:"mcq",micro:"Terapan: menjaga privasi & keamanan saat berteman lintas negara",q:"Kamu berteman daring dengan seseorang dari negara lain lewat komunitas hobi. Sikap yang aman sekaligus terbuka:",options:["langsung membagikan alamat & data pribadi karena ingin akrab","nikmati bertukar cerita, tetap jaga data pribadi, & libatkan orang dewasa bila ada hal yang membuatmu tidak nyaman","menolak berteman dengan siapa pun dari luar negeri"],answer:1,explain:"Keterbukaan pada dunia tetap perlu berjalan bersama kebiasaan keamanan digital dasar.",hint:"Terbuka bertukar cerita, tetap jaga data pribadi."},
{n:50,type:"mcq",micro:"Terapan: menghadapi ejekan pada identitas ganda",q:"Seorang teman berdarah campuran (dua negara/budaya) diejek 'tidak jelas asalnya'. Sikap membela yang baik:",options:["ikut mengejek agar diterima kelompok","membela dengan tenang, jelaskan bahwa identitas ganda adalah hal yang sah & memperkaya, bukan kekurangan","diam saja karena bukan urusanmu"],answer:1,explain:"Membela teman dengan identitas majemuk menunjukkan pemahaman bahwa kewargaan & identitas bisa berlapis.",hint:"Bela dengan tenang; identitas ganda itu sah."},
{n:51,type:"mcq",micro:"Terapan: memilih konten hiburan",q:"Untuk memperluas pemahaman tentang dunia lewat hiburan, kebiasaan yang membantu:",options:["hanya menonton konten dari satu negara saja seumur hidup","sesekali menonton/membaca karya dari negara atau budaya berbeda, dengan subtitle atau terjemahan bila perlu","menghindari semua konten dari luar negeri"],answer:1,explain:"Paparan yang beragam terhadap cerita dari berbagai belahan dunia memperluas cara pandang dengan cara yang menyenangkan.",hint:"Variasikan sumber tontonan/bacaanmu."},
{n:52,type:"open",micro:"Terapan: rencana aksi warga dunia",q:"Rancang tiga tindakan sederhana yang bisa kamu mulai bulan ini untuk menjadi warga dunia yang lebih baik.",sample:"1) Membaca satu artikel berita internasional dari sumber tepercaya setiap minggu & mendiskusikannya dengan keluarga. 2) Belajar menyapa 'halo' & 'terima kasih' dalam tiga bahasa berbeda. 3) Mengurangi penggunaan plastik sekali pakai di sekolah & mengajak dua teman melakukan hal yang sama, sebagai kontribusi kecil pada isu lingkungan global.",explain:"Rencana yang konkret & terukur membuat niat menjadi warga dunia lebih mungkin benar-benar dijalankan.",hint:"3 tindakan konkret yang bisa dimulai bulan ini."},
{n:53,type:"mcq",micro:"Terapan: menyikapi kesalahan berbahasa",q:"Seorang teman dari negara lain salah mengucapkan kata dalam bahasamu saat mencoba berbicara denganmu. Sikap yang mendukung:",options:["menertawakannya di depan umum","menghargai usahanya & membantu memperbaikinya dengan sabar & ramah","mengabaikan usahanya sepenuhnya"],answer:1,explain:"Mendukung usaha seseorang belajar bahasa/budaya baru mendorong keterbukaan, bukan mempermalukannya.",hint:"Hargai usahanya, bantu dengan sabar."},
{n:54,type:"tf",micro:"Terapan: transparansi & kepercayaan",q:"Benar atau Salah: Saat kelas menggalang bantuan untuk isu global, mencatat & melaporkan penggunaan dana secara terbuka membantu menjaga kepercayaan orang yang menyumbang.",answer:true,explain:"Transparansi adalah bagian penting dari tanggung jawab warga dunia yang mengelola kepercayaan orang lain.",hint:"Transparan menjaga kepercayaan."},
{n:55,type:"mcq",micro:"Terapan: menyikapi generalisasi teman",q:"Seorang teman berkata 'semua turis dari negara X berperilaku buruk' berdasarkan satu pengalaman. Tanggapan yang membangun:",options:["setuju & ikut menyebarkan anggapan itu","ingatkan bahwa satu pengalaman tidak mewakili semua warga suatu negara, & ajak melihat kasus per kasus","memusuhi semua turis dari negara itu"],answer:1,explain:"Menyanggah generalisasi berbasis pengalaman tipis membantu melawan prasangka yang tidak adil.",hint:"Satu pengalaman ≠ mewakili semua warga negara itu."},
{n:56,type:"order",micro:"Terapan: menangani konflik berbau prasangka",q:"Dua kelompok murid dari latar belakang berbeda bersitegang karena prasangka yang salah paham. Urutkan langkah membantu:",items:["Dengarkan kedua pihak tanpa memihak dulu","Bantu mereka mengenali bahwa prasangka itu berdasar anggapan, bukan fakta tentang individu masing-masing","Fasilitasi percakapan langsung yang tenang antara wakil kedua kelompok","Dorong kegiatan bersama untuk membangun pengertian lebih lanjut"],answer:[0,1,2,3],explain:"Dengar tanpa memihak → bongkar prasangka → percakapan langsung → kegiatan bersama membangun pengertian.",hint:"Dengar dulu, kegiatan bersama di akhir."},
{n:57,type:"mcq",micro:"Terapan: menyikapi privilese",q:"Kamu menyadari bahwa kamu punya akses pendidikan yang lebih baik dibanding anak-anak di beberapa wilayah dunia lain. Sikap yang matang:",options:["merasa bersalah tanpa melakukan apa-apa","bersyukur & menggunakan kesempatan itu sebaik mungkin, sambil mencari cara mendukung akses pendidikan yang lebih merata sesuai kemampuanmu","menyembunyikan atau menyangkal kesempatan yang kamu miliki"],answer:1,explain:"Menyadari privilese sebaiknya mendorong rasa syukur & tindakan, bukan rasa bersalah yang melumpuhkan.",hint:"Syukur + tindakan, bukan rasa bersalah kosong."},
{n:58,type:"mcq",micro:"Terapan: mendukung teman yang rindu kampung halaman",q:"Teman pindahan dari negara/daerah lain terlihat rindu rumahnya. Dukungan yang baik:",options:["menyuruhnya melupakan rumah lamanya","tanyakan dengan tulus tentang tempat asalnya & bantu ia merasa diterima di tempat baru tanpa harus melupakan asalnya","mengabaikan perasaannya"],answer:1,explain:"Mendukung adaptasi seseorang tidak berarti meminta mereka menghapus identitas atau kerinduannya.",hint:"Bantu beradaptasi tanpa memaksa melupakan asal."},
{n:59,type:"tf",micro:"Terapan: konsistensi nilai",q:"Benar atau Salah: Nilai keadilan & rasa hormat yang kita terapkan pada orang-orang di sekitar kita seharusnya juga kita terapkan saat berbicara atau bersikap tentang orang dari negara lain yang tidak kita kenal langsung.",answer:true,explain:"Kewargaan global yang konsisten menerapkan nilai yang sama pada orang dekat maupun orang jauh yang tidak kita kenal.",hint:"Nilai yang sama, dekat maupun jauh."},
{n:60,type:"mcq",micro:"Ringkasan Penerapan",q:"Menerapkan kewargaan global dalam keseharian berarti...",options:["menyambut yang berbeda dengan hangat, menolak ujaran kebencian, memilih sumber informasi & bantuan dengan bijak, & menjaga konsistensi nilai pada siapa pun","hanya berbicara tentang dunia tanpa bertindak","mengabaikan lingkungan sendiri demi isu global"],answer:0,explain:"Kewargaan global menjadi nyata lewat kebiasaan sehari-hari, bukan sekadar wawasan.",hint:"Sambut hangat, tolak kebencian, pilih bijak, konsisten nilai."},
// PHASE D — PENALARAN (61-80)
{n:61,type:"mcq",micro:"Menimbang loyalitas berlapis",q:"Saat kepentingan negara sendiri & kepentingan kemanusiaan global tampak berbeda arah (mis. dalam isu lingkungan), warga dunia yang matang akan...",options:["selalu mengutamakan negara sendiri tanpa mempertimbangkan dampak global","mencari solusi yang menghormati kebutuhan negaranya sambil mempertimbangkan dampaknya pada dunia yang lebih luas, bukan memilih salah satu secara membabi buta","selalu mengutamakan dunia & mengabaikan negaranya sendiri"],answer:1,explain:"Loyalitas berlapis (lokal, nasional, global) memerlukan penyeimbangan yang bijak, bukan pilihan ekstrem.",hint:"Cari solusi yang menyeimbangkan, bukan memilih ekstrem."},
{n:62,type:"mcq",micro:"Universalisme & penghormatan konteks",q:"Menjunjung hak asasi manusia yang universal sambil menghormati keragaman budaya bisa dilakukan dengan...",options:["menganggap semua praktik budaya harus sama di seluruh dunia","memahami bahwa cara mengekspresikan nilai bisa beragam antarbudaya, sementara martabat & hak dasar manusia tetap menjadi batas yang tidak bisa dilanggar","mengabaikan hak asasi manusia demi menghormati semua budaya tanpa kecuali"],answer:1,explain:"Ini adalah keseimbangan antara menghormati keragaman & menjaga standar kemanusiaan yang mendasar.",hint:"Ekspresi budaya beragam; hak dasar manusia tetap jadi batas."},
{n:63,type:"tf",micro:"Kompleksitas isu internasional",q:"Benar atau Salah: Isu-isu hubungan antarnegara sering melibatkan sejarah, kepentingan ekonomi, & politik yang kompleks, sehingga jarang bisa disederhanakan menjadi 'satu pihak sepenuhnya benar, satu pihak sepenuhnya salah'.",answer:true,explain:"Memahami kompleksitas ini membantu kita berpikir lebih matang tentang berita & isu internasional.",hint:"Jarang sesederhana 'benar total vs salah total'."},
{n:64,type:"mcq",micro:"Menyikapi propaganda & framing",q:"Sebuah negara/kelompok menyebarkan cerita yang hanya menampilkan sisi mereka tentang sebuah konflik. Sikap kritis:",options:["percaya penuh pada satu sisi cerita","sadari bahwa tiap pihak dalam konflik bisa membingkai cerita untuk kepentingannya, sehingga mencari sumber independen & beberapa sudut pandang penting","mengabaikan konflik itu sepenuhnya"],answer:1,explain:"Waspada pada framing sepihak adalah bagian dari literasi media & kewargaan global yang kritis.",hint:"Cari sumber independen & sudut pandang beragam."},
{n:65,type:"mcq",micro:"Tanggung jawab tidak merata",q:"Dalam isu global seperti perubahan iklim, tanggung jawab tiap negara berbeda karena...",options:["semua negara harus menanggung beban yang sama rata tanpa melihat kontribusi historisnya","kontribusi & kemampuan tiap negara berbeda, sehingga prinsip keadilan mempertimbangkan siapa yang lebih banyak berkontribusi pada masalah & siapa yang lebih mampu membantu","hanya negara kecil yang bertanggung jawab"],answer:1,explain:"Warga dunia yang paham keadilan global mengenali bahwa tanggung jawab yang adil bukan berarti selalu dibagi rata.",hint:"Sesuai kontribusi & kemampuan, bukan rata sama besar."},
{n:66,type:"open",micro:"Menimbang dilema kewargaan global",q:"Sebuah perusahaan di negaramu ingin berinvestasi di negara lain, membuka lapangan kerja tetapi juga berisiko pada lingkungan setempat. Tuliskan pertimbangan untuk kedua sisi & satu syarat yang bisa membuatnya lebih bertanggung jawab.",sample:"Sisi positif: investasi bisa membuka lapangan kerja & meningkatkan ekonomi masyarakat setempat. Sisi risiko: bila tidak dikelola baik, bisa merusak lingkungan & tidak adil bagi warga lokal yang menanggung dampaknya. Syarat agar lebih bertanggung jawab: perusahaan harus mematuhi standar lingkungan yang ketat, melibatkan & mendengarkan masyarakat setempat, serta memastikan sebagian keuntungan benar-benar dirasakan warga lokal, bukan hanya pemilik modal.",explain:"Dilema seperti ini menuntut warga dunia menimbang manfaat ekonomi & tanggung jawab pada manusia serta lingkungan sekaligus.",hint:"Manfaat + risiko + syarat tanggung jawab."},
{n:67,type:"mcq",micro:"Menghindari 'penyelamat' yang merendahkan",q:"Saat membantu komunitas di negara lain yang menghadapi kesulitan, sikap yang perlu dihindari:",options:["mendengarkan kebutuhan mereka sendiri","menempatkan diri sebagai 'penyelamat' yang tahu segalanya tanpa mendengarkan apa yang sebenarnya mereka butuhkan & inginkan","bekerja sama dengan pemimpin & organisasi lokal"],answer:1,explain:"Bantuan yang efektif & hormat mendengarkan suara komunitas yang dibantu, bukan memaksakan solusi dari luar tanpa konsultasi.",hint:"Hindari sikap 'aku tahu lebih baik dari mereka'."},
{n:68,type:"tf",micro:"Kewargaan global & keadilan lokal",q:"Benar atau Salah: Peduli pada isu global tidak seharusnya membuat kita mengabaikan ketidakadilan yang terjadi di lingkungan atau negara kita sendiri.",answer:true,explain:"Kewargaan global yang seimbang tetap memperhatikan keadilan di rumah sendiri, bukan hanya isu-isu jauh yang terdengar lebih menarik.",hint:"Jangan abaikan keadilan di rumah sendiri."},
{n:69,type:"mcq",micro:"Bahasa & kekuasaan",q:"Beberapa bahasa lebih dominan digunakan secara internasional (mis. dalam bisnis atau sains). Kesadaran warga dunia tentang hal ini:",options:["menganggap bahasa lain tidak penting untuk dipelajari","menyadari dominasi ini punya sejarahnya sendiri, sambil tetap menghargai & mendukung pelestarian bahasa-bahasa yang kurang dominan","menganggap semua bahasa harus diseragamkan"],answer:1,explain:"Menyadari ketimpangan dominasi bahasa membantu kita menghargai keragaman linguistik yang berharga.",hint:"Sadari sejarahnya, tetap hargai bahasa yang kurang dominan."},
{n:70,type:"order",micro:"Menilai klaim tentang 'negara terbaik'",q:"Kamu membaca klaim 'Negara X adalah negara terbaik di dunia untuk segalanya'. Urutkan cara menilainya:",items:["Tanyakan: terbaik menurut ukuran apa (pendidikan, kesehatan, kebahagiaan, ekonomi)?","Sadari bahwa 'terbaik untuk segalanya' sangat menyederhanakan — tiap negara punya kekuatan & kelemahan berbeda-beda","Cari data pembanding dari sumber yang independen untuk ukuran spesifik yang relevan","Simpulkan dengan hati-hati, menghindari peringkat mutlak yang menyeluruh"],answer:[0,1,2,3],explain:"Klaim 'terbaik di segala hal' hampir selalu menyederhanakan realitas yang kompleks & beragam ukurannya.",hint:"Tanyakan standar penilaiannya dulu."},
{n:71,type:"tf",micro:"Kewargaan global bukan seragam pemikiran",q:"Benar atau Salah: Menjadi warga dunia berarti semua orang harus berpikir & berpendapat persis sama tentang setiap isu global.",answer:false,explain:"Sebaliknya, warga dunia yang matang bisa berbeda pendapat tentang solusi, sambil tetap berbagi nilai dasar seperti hormat & kepedulian pada kemanusiaan.",hint:"Boleh beda pendapat, nilai dasarnya yang dibagikan bersama."},
{n:72,type:"mcq",micro:"Menyikapi ketegangan sejarah",q:"Dua negara punya sejarah ketegangan panjang (mis. bekas penjajahan). Sikap warga dunia muda yang membangun:",options:["mengulangi kebencian lama tanpa berpikir","memahami sejarahnya dengan jujur, tanpa mewariskan kebencian yang tidak perlu pada generasi sekarang, & terbuka pada rekonsiliasi","melupakan sejarah sepenuhnya seolah tidak pernah terjadi"],answer:1,explain:"Memahami sejarah penting untuk konteks, tetapi generasi baru punya kesempatan membangun hubungan yang lebih baik daripada terus mewarisi kebencian.",hint:"Pahami sejarah, jangan wariskan kebencian tanpa perlu."},
{n:73,type:"mcq",micro:"Kewargaan global & kesetaraan gender/kelompok",q:"Prinsip kewargaan global tentang martabat semua manusia berarti mendukung...",options:["hanya kesetaraan bagi kelompok tertentu saja","kesempatan & perlakuan yang adil bagi semua orang, tanpa memandang gender, suku, agama, atau latar belakang lain, di mana pun mereka berada","tidak perlu memikirkan kesetaraan sama sekali"],answer:1,explain:"Prinsip martabat universal mencakup semua kelompok manusia, bukan sebagian saja.",hint:"Adil untuk semua kelompok, di mana pun."},
{n:74,type:"open",micro:"Refleksi dilema nilai",q:"Ceritakan situasi (nyata atau bayangan) di mana kamu harus menimbang antara loyalitas pada kelompok dekatmu (keluarga, sekolah, negara) & nilai keadilan yang lebih luas. Bagaimana kamu menyikapinya atau akan menyikapinya?",sample:"Bayangkan timku bermain curang dalam pertandingan antarsekolah & menang karenanya. Loyalitas pada tim membuatku ingin diam saja karena timku menang. Tapi nilai keadilan membuatku merasa itu tidak benar bagi tim lawan. Aku akan mencoba membicarakannya baik-baik dengan pelatih atau kapten tim secara pribadi, menyuarakan bahwa kemenangan yang adil lebih berharga daripada menang dengan cara curang, tanpa mempermalukan tim di depan umum.",explain:"Menimbang loyalitas & keadilan adalah keterampilan kewargaan yang matang, & tidak selalu ada jawaban mudah.",hint:"Situasi + cara menyikapi yang menghormati keduanya sebisa mungkin."},
{n:75,type:"mcq",micro:"Batas antara kritik & campur tangan",q:"Menyuarakan kepedulian tentang isu di negara lain (mis. lewat kampanye kesadaran) berbeda dari...",options:["tidak ada bedanya sama sekali","memaksakan kehendak atau campur tangan yang tidak diminta & tidak menghormati kedaulatan serta suara masyarakat setempat","peduli pada isu di negara lain sama sekali dilarang"],answer:1,explain:"Kepedulian global yang matang menghormati batas antara menyuarakan dukungan & memaksakan solusi dari luar.",hint:"Peduli & mendukung ≠ memaksakan kehendak."},
{n:76,type:"tf",micro:"Empati untuk yang berbeda pandangan",q:"Benar atau Salah: Berempati & mencoba memahami mengapa seseorang punya pandangan politik/sosial yang sangat berbeda dari kita tidak berarti kita harus setuju dengan pandangan itu.",answer:true,explain:"Memahami sudut pandang orang lain adalah keterampilan terpisah dari menyetujuinya.",hint:"Paham berbeda dari setuju."},
{n:77,type:"mcq",micro:"Menyikapi ketimpangan yang tak sepenuhnya bisa diselesaikan sendiri",q:"Sebagai pelajar, kamu sadar ada ketimpangan global besar yang tidak bisa kamu selesaikan sendirian. Sikap yang sehat:",options:["merasa tidak berdaya & berhenti peduli sama sekali","terima bahwa perubahan besar butuh banyak orang & waktu, lalu fokus pada peran kecil yang bisa kamu mainkan sekarang sebagai bagian dari usaha bersama","memaksakan diri menyelesaikan semuanya sendirian"],answer:1,explain:"Menerima keterbatasan diri sambil tetap berkontribusi adalah sikap yang berkelanjutan, berbeda dari putus asa atau memaksakan diri berlebihan.",hint:"Terima keterbatasan, tetap berkontribusi sesuai peran."},
{n:78,type:"mcq",micro:"Kewargaan global & masa depan pekerjaan",q:"Memahami dunia yang saling terhubung bisa membantu pelajar mempersiapkan diri untuk masa depan karena...",options:["tidak ada kaitannya dengan pekerjaan","banyak pekerjaan masa depan melibatkan kerja sama lintas negara/budaya, sehingga keterampilan lintas budaya menjadi bekal berharga","semua pekerjaan hanya akan bersifat lokal selamanya"],answer:1,explain:"Keterampilan memahami & bekerja dengan orang dari berbagai latar belakang makin dibutuhkan di dunia kerja yang terhubung.",hint:"Bekal untuk kerja sama lintas negara di masa depan."},
{n:79,type:"tf",micro:"Kewargaan global sebagai keterampilan, bukan hanya sikap",q:"Benar atau Salah: Menjadi warga dunia melibatkan keterampilan yang bisa dilatih (mendengarkan, memeriksa sumber, berkomunikasi lintas budaya), bukan hanya perasaan baik semata.",answer:true,explain:"Seperti keterampilan lain, kewargaan global membutuhkan latihan & praktik, bukan hanya niat baik.",hint:"Keterampilan yang dilatih, bukan cuma niat."},
{n:80,type:"mcq",micro:"Ringkasan Penalaran",q:"Cara berpikir matang tentang kewargaan global mencakup...",options:["menyeimbangkan loyalitas berlapis, menghormati konteks sambil menjunjung hak dasar manusia, waspada pada framing sepihak, & menerima kompleksitas tanpa jatuh ke sinisme atau kepolosan berlebihan","memilih satu loyalitas & mengabaikan yang lain","percaya semua klaim tentang negara & isu global tanpa menyaring"],answer:0,explain:"Kematangan kewargaan global menuntut kemampuan menimbang, bukan jawaban sederhana untuk pertanyaan yang rumit.",hint:"Seimbangkan loyalitas, hormati konteks & HAM, waspada framing, terima kompleksitas."},
// PHASE E — TANTANGAN (81-100)
{n:81,type:"mcq",micro:"Sintesis: dari CIV-09 sampai CIV-12",q:"Menghubungkan pembelajaran tentang dunia yang terhubung, budaya dunia, masalah bersama, & kewargaan global, benang merahnya adalah...",options:["dunia ini penuh masalah tanpa harapan","kita hidup dalam satu jaringan kemanusiaan yang saling terhubung & beragam, menghadapi tantangan bersama, & masing-masing dari kita punya peran dalam menjaganya dengan hormat & tanggung jawab","hanya negara besar yang penting dalam dunia ini"],answer:1,explain:"Empat topik ini bersama-sama membentuk gambaran: dunia yang terhubung, beragam, penuh tantangan, & membutuhkan warga yang peduli & bertanggung jawab.",hint:"Terhubung + beragam + tantangan bersama + peran tiap orang."},
{n:82,type:"open",micro:"Proyek warga dunia pribadi",q:"Rancang 'proyek warga dunia pribadi' untuk satu semester ke depan: pilih satu isu (dari dunia terhubung, budaya, atau masalah global), satu cara belajar, & satu tindakan nyata yang akan kamu lakukan secara konsisten.",sample:"Isu: kesenjangan akses pendidikan di berbagai wilayah dunia. Cara belajar: membaca satu artikel atau menonton satu dokumentari tepercaya setiap bulan tentang isu ini, & mencatat hal baru yang kupelajari. Tindakan nyata: menjadi tutor sukarela membantu adik kelas yang kesulitan belajar setiap minggu, sebagai kontribusi nyata pada pemerataan pendidikan di lingkunganku sendiri, sambil terus belajar tentang isu ini secara lebih luas.",explain:"Proyek pribadi yang jelas & konsisten mengubah kesadaran menjadi kebiasaan nyata sepanjang waktu.",hint:"1 isu + 1 cara belajar rutin + 1 tindakan nyata konsisten."},
{n:83,type:"mcq",micro:"Menyikapi kritik terhadap gagasan 'warga dunia'",q:"Sebagian orang skeptis pada gagasan 'warga dunia', khawatir ini mengabaikan pentingnya negara & komunitas lokal. Tanggapan yang seimbang:",options:["mengabaikan kekhawatiran ini sepenuhnya","kekhawatiran ini valid untuk diperhatikan — kewargaan global yang sehat justru menguatkan, bukan menggantikan, akar lokal & nasional seseorang","setuju sepenuhnya bahwa negara & komunitas lokal tidak penting"],answer:1,explain:"Menanggapi kritik dengan serius & menjelaskan bahwa kewargaan global dimaksudkan sebagai tambahan, bukan pengganti, adalah sikap yang matang.",hint:"Kritik itu valid; jelaskan bahwa ini melengkapi, bukan mengganti."},
{n:84,type:"tf",micro:"Kewargaan global butuh kerendahan hati",q:"Benar atau Salah: Warga dunia yang matang bersedia mengakui bahwa pemahamannya tentang budaya atau isu tertentu masih terbatas, & tetap terbuka untuk terus belajar & diperbaiki.",answer:true,explain:"Kerendahan hati intelektual adalah bagian penting dari kewargaan global yang sehat, mencegah kita merasa sudah tahu segalanya.",hint:"Mengakui keterbatasan, tetap terbuka belajar."},
{n:85,type:"mcq",micro:"Menyikapi perbedaan kecepatan kemajuan",q:"Beberapa wilayah dunia mengalami kemajuan pada suatu isu lebih cepat dari wilayah lain karena perbedaan sumber daya & sejarah. Sikap yang adil:",options:["menyalahkan wilayah yang lebih lambat sebagai 'malas'","memahami faktor struktural di balik perbedaan kecepatan kemajuan, & mendukung upaya membantu wilayah yang tertinggal mendapat kesempatan yang lebih setara","mengabaikan wilayah yang lebih lambat sepenuhnya"],answer:1,explain:"Memahami akar struktural ketimpangan mencegah kita menyalahkan korban ketimpangan atas kondisi yang bukan sepenuhnya pilihan mereka.",hint:"Faktor struktural, bukan sekadar 'malas'."},
{n:86,type:"order",micro:"Dari kesadaran ke warisan",q:"Urutkan bagaimana kesadaran seorang pelajar tentang kewargaan global bisa berkembang menjadi warisan jangka panjang:",items:["Belajar & membangun kebiasaan peduli sejak usia sekolah","Membawa nilai & keterampilan itu ke pilihan pendidikan/pekerjaan di masa depan","Menularkan nilai kewargaan global itu pada orang di sekitarnya (keluarga, teman, komunitas)","Menjadi bagian dari generasi yang mewariskan dunia yang sedikit lebih baik pada generasi berikutnya"],answer:[0,1,2,3],explain:"Kebiasaan yang dibangun sejak muda bisa tumbuh menjadi kontribusi jangka panjang bagi generasi mendatang.",hint:"Mulai dari kebiasaan sekarang, berujung pada warisan jangka panjang."},
{n:87,type:"mcq",micro:"Menggabungkan seluruh keterampilan CIV",q:"Menjadi warga yang baik secara menyeluruh (dari CIV-01 sampai CIV-12) berarti menggabungkan...",options:["hanya menaati aturan tanpa peduli hal lain","memahami hak & kewajiban, menghargai keberagaman, ikut menjaga lingkungan & milik bersama, peduli pada dunia yang terhubung & budaya global, serta bertindak sebagai warga yang bertanggung jawab di semua tingkat — lokal, nasional, & global","hanya peduli pada isu global & mengabaikan aturan lokal"],answer:1,explain:"Seluruh rangkaian CIV membentuk gambaran warga yang utuh: bertanggung jawab dari lingkup terdekat sampai dunia.",hint:"Gabungan semua topik CIV, dari lokal sampai global."},
{n:88,type:"open",micro:"Surat untuk diri sendiri di masa depan",q:"Tulis surat singkat (4-5 kalimat) untuk dirimu sendiri 10 tahun dari sekarang, tentang jenis warga dunia yang kamu harap sudah menjadi.",sample:"Untuk diriku 10 tahun lagi, aku harap kamu masih penasaran & terus belajar tentang dunia, tidak menutup diri walau sibuk dengan urusan sendiri. Aku harap kamu memperlakukan orang dari latar belakang mana pun dengan hormat yang sama, & sudah melakukan setidaknya satu hal nyata untuk membantu isu global yang kamu pedulikan sejak remaja. Aku harap kamu tetap bangga menjadi bagian dari negerimu, sambil merasa menjadi bagian dari keluarga besar umat manusia. Jangan lupa bahwa langkah kecil yang kamu mulai hari ini adalah awal dari semua itu.",explain:"Menulis surat untuk diri masa depan menjadikan nilai kewargaan global sebagai komitmen jangka panjang, bukan sekadar pelajaran sesaat.",hint:"4-5 kalimat harapan untuk dirimu 10 tahun lagi."},
{n:89,type:"mcq",micro:"Menilai kemajuan diri sendiri",q:"Tanda bahwa pemahamanmu tentang kewargaan global sedang matang:",options:["kamu merasa sudah cukup tahu & berhenti bertanya","kamu semakin bisa memegang kebanggaan pada identitasmu sendiri & keterbukaan pada dunia sekaligus, tanpa merasa harus memilih salah satu","kamu semakin yakin negerimu sendiri harus dijadikan standar bagi semua negara"],answer:1,explain:"Kematangan terlihat dari kemampuan memegang lebih dari satu nilai sekaligus tanpa kontradiksi yang dipaksakan.",hint:"Bangga pada diri + terbuka pada dunia, sekaligus."},
{n:90,type:"tf",micro:"Tujuan akhir",q:"Benar atau Salah: Tujuan menjadi warga dunia adalah membangun kepedulian, pemahaman, & tanggung jawab yang nyata terhadap sesama manusia & planet ini — bukan sekadar gelar atau status yang dibanggakan.",answer:true,explain:"Kewargaan global yang sejati terlihat dari tindakan & sikap sehari-hari, bukan dari label semata.",hint:"Tindakan nyata, bukan sekadar label."},
{n:91,type:"mcq",micro:"Menyikapi rasa kewalahan pada skala dunia",q:"Memikirkan seluruh dunia & semua masalahnya sekaligus bisa terasa sangat besar bagi seorang pelajar. Cara menjaga agar tetap bisa bertindak:",options:["berhenti memikirkan dunia sama sekali","ingat bahwa kamu tidak perlu menyelesaikan semuanya sendirian; fokus pada lingkaran pengaruhmu (diri, keluarga, sekolah, komunitas) yang bisa kamu jangkau nyata","memaksakan diri memikirkan & menyelesaikan segalanya sekaligus"],answer:1,explain:"Fokus pada 'lingkaran pengaruh' yang bisa kita jangkau membuat kepedulian besar tetap bisa dijalani tanpa kewalahan.",hint:"Fokus lingkaran pengaruhmu, bukan seluruh dunia sekaligus."},
{n:92,type:"mcq",micro:"Warisan bersama umat manusia",q:"Konsep bahwa pengetahuan, seni, & pencapaian besar manusia (penemuan sains, karya seni, warisan sejarah) adalah 'milik bersama umat manusia' berarti...",options:["hanya negara penemunya yang boleh menikmatinya","pencapaian besar itu layak dijaga & bisa menjadi kebanggaan serta inspirasi bagi semua manusia, meski lahir dari satu tempat tertentu","pencapaian itu tidak penting bagi orang di luar negara asalnya"],answer:1,explain:"Melihat pencapaian manusia sebagai warisan bersama memperkuat rasa memiliki & kebanggaan kolektif sebagai satu spesies.",hint:"Kebanggaan & inspirasi bersama, meski lahir di satu tempat."},
{n:93,type:"open",micro:"Refleksi menyeluruh",q:"Setelah mempelajari seluruh rangkaian tentang dunia yang terhubung, budaya, masalah global, & kewargaan dunia, tuliskan 2-3 kalimat tentang jenis warga dunia seperti apa yang ingin kamu menjadi.",sample:"Aku ingin menjadi warga dunia yang tetap bangga & berakar pada budaya serta negeriku sendiri, sambil terus penasaran & belajar tentang tempat dan orang lain di dunia dengan rasa hormat. Aku ingin memperlakukan siapa pun dengan adil tanpa memandang dari mana mereka berasal, & melakukan bagianku — sekecil apa pun — untuk isu-isu yang kupedulikan, percaya bahwa banyak langkah kecil bisa menyatu menjadi perubahan besar.",explain:"Merumuskan visi pribadi tentang kewargaan dunia menjadi penutup yang bermakna untuk seluruh pembelajaran topik ini.",hint:"2-3 kalimat visi, dengan katamu sendiri."},
{n:94,type:"mcq",micro:"Menghubungkan dengan keterampilan lain",q:"Kewargaan global bekerja paling baik bila digabung dengan keterampilan lain yang sudah kamu pelajari, seperti...",options:["hanya menghafal fakta tentang negara-negara","berpikir kritis (menilai klaim & sumber), komunikasi & kolaborasi (bekerja dengan orang berbeda latar), serta kecerdasan emosi (empati & mengelola perbedaan pendapat)","tidak perlu digabung dengan keterampilan apa pun"],answer:1,explain:"Kewargaan global adalah simpul yang menyatukan banyak keterampilan yang sudah dipelajari di domain lain.",hint:"Gabung dengan berpikir kritis, komunikasi, kolaborasi, kecerdasan emosi."},
{n:95,type:"tf",micro:"Peran generasi ini",q:"Benar atau Salah: Generasi pelajar hari ini akan mewarisi & membentuk dunia yang makin terhubung, sehingga belajar menjadi warga dunia yang baik adalah investasi penting untuk masa depan bersama.",answer:true,explain:"Bagaimana generasi ini bersikap & bertindak akan membentuk seperti apa dunia yang terhubung ini ke depannya.",hint:"Investasi untuk masa depan bersama."},
{n:96,type:"mcq",micro:"Menghindari dua sikap ekstrem terakhir",q:"Dua sikap ekstrem yang sebaiknya dihindari sebagai warga dunia:",options:["menutup diri sepenuhnya dari dunia luar & menganggap identitas sendiri satu-satunya yang benar, ATAU melarutkan diri sepenuhnya tanpa akar & kehilangan identitas sendiri demi terlihat 'mendunia'","hanya sikap pertama yang bermasalah","tidak ada sikap yang perlu dihindari"],answer:0,explain:"Kewargaan global yang sehat berada di tengah: berakar kuat sekaligus terbuka luas, bukan salah satu ekstrem.",hint:"Bukan menutup total, bukan pula larut tanpa akar."},
{n:97,type:"mcq",micro:"Ukuran keberhasilan pribadi",q:"Ukuran yang lebih bermakna untuk menilai perjalananmu menjadi warga dunia:",options:["seberapa banyak negara yang pernah kamu kunjungi","seberapa konsisten sikap hormat, rasa ingin tahu, & tindakan nyatamu terhadap sesama manusia & lingkungan, di mana pun kamu berada","seberapa banyak bahasa asing yang kamu kuasai"],answer:1,explain:"Kewargaan global sejati diukur dari sikap & tindakan konsisten, bukan dari jumlah negara yang dikunjungi atau bahasa yang dikuasai semata (meski keduanya bisa membantu).",hint:"Konsistensi sikap & tindakan, bukan sekadar pengalaman/kemampuan."},
{n:98,type:"order",micro:"Menghidupi nilai sehari-hari",q:"Urutkan bagaimana nilai kewargaan global bisa hidup dalam satu hari biasa seorang pelajar:",items:["Bangun pagi & bersyukur pada kesempatan yang dimiliki, sadar tidak semua anak seberuntung ini","Di sekolah, bersikap ramah & terbuka pada teman dari latar belakang apa pun","Sore hari, membaca satu berita global dari sumber tepercaya dengan pikiran kritis","Malam hari, melakukan satu kebiasaan kecil bertanggung jawab (hemat listrik/air, tidak menyebar info salah, dsb.)"],answer:[0,1,2,3],explain:"Nilai kewargaan global paling kuat ketika hidup dalam rutinitas harian, bukan hanya dipikirkan sesekali.",hint:"Dari bangun pagi sampai malam hari."},
{n:99,type:"open",micro:"Janji warga dunia",q:"Tuliskan 'janji warga dunia' pribadimu (3-4 kalimat) sebagai penutup topik ini.",sample:"Aku berjanji untuk terus belajar tentang dunia & budaya yang berbeda dariku dengan rasa hormat & rasa ingin tahu yang tulus. Aku akan memperlakukan setiap orang dengan adil, apa pun latar belakangnya, & berani menolak ujaran kebencian atau prasangka yang kutemui. Aku akan mengambil tindakan kecil yang konsisten untuk isu yang kupedulikan, sambil tetap bangga & menjaga akar budaya serta negeriku sendiri. Aku percaya, sekecil apa pun peranku, aku adalah bagian dari usaha bersama umat manusia untuk dunia yang lebih baik.",explain:"Janji pribadi yang ditulis dengan sungguh-sungguh menjadi penutup yang kuat untuk seluruh rangkaian pembelajaran kewargaan & literasi global.",hint:"3-4 kalimat komitmen menyeluruh, dengan katamu sendiri."},
{n:100,type:"mcq",micro:"Ringkasan Tantangan (Kapstone)",q:"Inti menjadi warga dunia yang matang, merangkum seluruh rangkaian dunia terhubung, budaya, masalah bersama, & kewargaan global:",options:["menyadari kemanusiaan bersama di tengah keragaman, tetap berakar pada identitas & negeri sendiri, memahami tantangan dunia dengan jujur & berbasis bukti, serta bertindak dengan hormat & tanggung jawab dalam lingkaran pengaruh yang bisa dijangkau — sekecil apa pun, sebagai bagian dari usaha bersama yang lebih besar","hanya peduli pada negara sendiri & mengabaikan dunia","hanya peduli pada dunia & melupakan negeri sendiri"],answer:0,explain:"Warga dunia yang matang menyatukan akar yang kuat, pandangan yang luas, kejujuran tentang tantangan, & tindakan nyata yang konsisten — inilah puncak dari seluruh perjalanan belajar kewargaan & literasi global.",hint:"Kemanusiaan bersama + akar sendiri + jujur pada tantangan + bertindak nyata."},
];
